import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr == len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] u = new int[m];
        int[] v = new int[m];
        int[] degree = new int[n];

        for (int i = 0; i < m; i++) {
            u[i] = fs.nextInt() - 1;
            v[i] = fs.nextInt() - 1;
            degree[u[i]]++;
            degree[v[i]]++;
        }

        int[] offset = new int[n + 1];
        for (int i = 0; i < n; i++) {
            offset[i + 1] = offset[i] + degree[i];
        }

        int[] cursor = offset.clone();
        long[] adjacency = new long[2 * m];

        for (int i = 0; i < m; i++) {
            int id = 2 * i;
            adjacency[cursor[u[i]]++] = ((long) v[i] << 32) | (id & 0xffffffffL);
            adjacency[cursor[v[i]]++] = ((long) u[i] << 32) | ((id + 1) & 0xffffffffL);
        }

        int[] position = new int[2 * m];
        for (int x = 0; x < n; x++) {
            Arrays.sort(adjacency, offset[x], offset[x + 1]);
            for (int p = offset[x]; p < offset[x + 1]; p++) {
                position[(int) adjacency[p]] = p - offset[x];
            }
        }

        int[] fenwickOffset = new int[n];
        int fenwickSize = 0;
        for (int x = 0; x < n; x++) {
            fenwickOffset[x] = fenwickSize;
            fenwickSize += degree[x] + 1;
        }
        int[] fenwick = new int[fenwickSize];

        int maxSum = 2 * n;
        int[] head = new int[maxSum + 1];
        Arrays.fill(head, -1);
        int[] next = new int[2 * m];

        for (int id = 0; id < 2 * m; id++) {
            int edge = id >>> 1;
            int a = (id & 1) == 0 ? u[edge] : v[edge];
            int b = (id & 1) == 0 ? v[edge] : u[edge];
            int sum = a + b;
            next[id] = head[sum];
            head[sum] = id;
        }

        int[] answer = new int[n];
        Arrays.fill(answer, 1);

        for (int sum = maxSum; sum >= 0; sum--) {
            for (int id = head[sum]; id != -1; id = next[id]) {
                int edge = id >>> 1;
                int from = (id & 1) == 0 ? u[edge] : v[edge];
                int to = (id & 1) == 0 ? v[edge] : u[edge];

                int left = offset[to], right = offset[to + 1];
                int lo = left, hi = right;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    int neighbor = (int) (adjacency[mid] >>> 32);
                    if (neighbor <= from) lo = mid + 1;
                    else hi = mid;
                }

                int countGreater = right - lo;
                int bestNext = 0;
                int base = fenwickOffset[to];
                for (int x = countGreater; x > 0; x -= x & -x) {
                    bestNext = Math.max(bestNext, fenwick[base + x]);
                }

                int length = bestNext == 0 ? 2 : bestNext + 1;
                answer[from] = Math.max(answer[from], length);

                int d = degree[from];
                int index = d - position[id];
                base = fenwickOffset[from];
                for (int x = index; x <= d; x += x & -x) {
                    if (fenwick[base + x] < length) {
                        fenwick[base + x] = length;
                    }
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) out.append(' ');
            out.append(answer[i]);
        }
        System.out.println(out);
    }
}
